use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::field::harness::Harness;
use semio_framework_value::{retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
use crate::field::harness::observe as observe_heap;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes.max(257),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(h:&mut Harness,value:T)->RetainedCloneSource<T>{h.source(value)}
fn close_source<T:RetireOwned+Sync+'static>(h:&mut Harness,source:RetainedCloneSource<T>){h.close_source(source)}
fn drain<T:RetireOwned>(h:&mut Harness,value:T){h.retire(value)}
fn nullable(value:&serde_json::Value)->Option<String>{value.as_str().map(str::to_string)}
type Run<'a>=&'a mut crate::field::harness::Harness;
fn step_decide<T:RetainedEquality+RetainedClone>(h:Run,p:&mut RetainedFieldChange<T>,a:&RetainedCloneSource<T>,o:&RetainedCloneSource<T>,g:RetainedCloneGrant)->RetainedCloneStep{h.turn(g,4096,&mut |e,r,rec|if rec{p.recover_decide_into(a.borrow(),o.borrow(),257,4096,e,r)}else{p.decide_into(a.borrow(),o.borrow(),257,4096,e,r)}).result.unwrap()}
fn step_inverse<T:RetainedEquality+RetainedClone>(h:Run,p:&mut RetainedFieldChange<T>,o:&RetainedCloneSource<T>,g:RetainedCloneGrant)->RetainedCloneStep{h.turn(g,4096,&mut |e,r,rec|if rec{p.recover_inverse_into(o.borrow(),257,4096,e,r)}else{p.inverse_into(o.borrow(),257,4096,e,r)}).result.unwrap()}
fn native_take<T>(h:Run,g:RetainedCloneGrant,call:impl FnOnce(&mut RetainedAllocationEffect<'_>,&mut Option<T>,crate::field::Reply<'_,RetainedCloneStep,ValueError>)->Result<(),ValueError>)->Option<(Option<T>,RetainedCloneProgress)>{let mut out=None;let mut slot=None;let(done,_,_)=h.native(g,1,|e|call(e,&mut out,semio_framework_value::retained_clone::OriginalEffectReply::borrow(&mut slot).unwrap()));done.unwrap();match slot.take().unwrap().unwrap(){RetainedCloneStep::Complete(p)=>Some((out,p)),RetainedCloneStep::Progress(_)=>None}}
fn take_change<T:RetainedEquality+RetainedClone>(h:Run,p:&mut RetainedFieldChange<T>,g:RetainedCloneGrant)->Option<(Option<T>,RetainedCloneProgress)>{native_take(h,g,|e,out,r|p.take_change_into(out,e,r).map(drop))}
fn take_inverse<T:RetainedEquality+RetainedClone>(h:Run,p:&mut RetainedFieldChange<T>,g:RetainedCloneGrant)->Option<(T,RetainedCloneProgress)>{native_take(h,g,|e,out,r|p.take_inverse_into(out,e,r).map(drop)).map(|(v,p)|(v.expect("inverse field"),p))}
fn close_turn<T:RetainedEquality+RetainedClone>(h:Run,p:&mut RetainedFieldChange<T>,g:RetainedCloneGrant,work:u64)->RetainedCloneStep{h.turn(g,work,&mut |e,r,rec|if rec{p.recover_close_into(4096,e,r)}else{p.close_into(4096,e,r)}).result.unwrap()}
fn close<T:RetainedEquality+RetainedClone>(h:Run,p:&mut RetainedFieldChange<T>){p.begin_close();let mut turns=0;while !p.terminal_is_empty(){let d=p.close_demand(4096).unwrap();let work=p.close_work_demand(4096).unwrap();let g=grant(d);assert_eq!(close_turn(h,p,RetainedCloneGrant{maximum_items:0,..g},work).progress(),Default::default());if d.release_bytes>0{assert_eq!(close_turn(h,p,RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g},work).progress(),Default::default());}assert!(close_turn(h,p,g,work).progress().fits(g));assert!({turns+=1;turns}<100000);}}

#[test]
fn optional_field_sparse_changes_and_inverse_preserve_original_sources(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let mut h=Harness::new();let mut authored=source(&mut h,nullable(&row["authored"]));let mut original=source(&mut h,nullable(&row["original"]));let pointer=original.borrow().get().as_ref().map(|text|text.as_ptr());let(mut field,heap)=observe_heap(RetainedFieldChange::<Option<String>>::default);assert_eq!(heap,(0,0));let mut turns=0;while !field.ready(){let g=grant(field.decision_demand(authored.borrow(),original.borrow(),257,4096).unwrap());assert_eq!(step_decide(&mut h,&mut field,&authored,&original,RetainedCloneGrant{maximum_items:0,..g}).progress(),Default::default());assert!(step_decide(&mut h,&mut field,&authored,&original,g).progress().fits(g));assert!({turns+=1;turns}<100000);}let g=grant(field.decision_demand(authored.borrow(),original.borrow(),257,4096).unwrap());let(change,p)=take_change(&mut h,&mut field,g).unwrap();assert!(p.fits(g));assert_eq!(change.is_none(),row["unchanged"].as_bool().unwrap());if let Some(change)=change.as_ref(){assert_eq!(change,&nullable(&row["change"]));}while !field.inverse_ready(){let g=grant(field.inverse_demand(original.borrow(),257,4096).unwrap());assert!(step_inverse(&mut h,&mut field,&original,g).progress().fits(g));assert!({turns+=1;turns}<100000);}let g=grant(field.inverse_take_demand().unwrap());let(inverse_value,p)=take_inverse(&mut h,&mut field,g).unwrap();assert!(p.fits(g));assert_eq!(inverse_value,nullable(&row["inverse"]));close(&mut h,&mut field);assert_eq!(original.borrow().get().as_ref().map(|text|text.as_ptr()),pointer);assert_eq!(observe_heap(||drop(field)).1,(0,0));drain(&mut h,change);drain(&mut h,inverse_value);close_source(&mut h,authored);close_source(&mut h,original);}}

#[test]
fn optional_field_partial_cancellation_and_foreign_sources_remain_owned(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for cut in fixture["cancelCuts"].as_array().unwrap().iter().map(|cut|cut.as_u64().unwrap()as usize){let mut h=Harness::new();let mut a=source(&mut h,nullable(&row["authored"]));let mut b=source(&mut h,nullable(&row["original"]));let mut foreign=source(&mut h,nullable(&row["authored"]));let pointer=b.borrow().get().as_ref().map(|text|text.as_ptr());let mut p=RetainedFieldChange::<Option<String>>::default();let mut turns=0;while !p.ready()&&turns<cut{let g=grant(p.decision_demand(a.borrow(),b.borrow(),257,4096).unwrap());assert!(step_decide(&mut h,&mut p,&a,&b,g).progress().fits(g));turns+=1;}if turns>0{assert!(p.equality.verify(foreign.borrow(),b.borrow()).is_err());}let mut change=None;let mut inverse=None;if p.ready()&&turns<cut{let g=grant(p.decision_demand(a.borrow(),b.borrow(),257,4096).unwrap());change=Some(take_change(&mut h,&mut p,g).unwrap().0);turns+=1;while !p.inverse_ready()&&turns<cut{let g=grant(p.inverse_demand(b.borrow(),257,4096).unwrap());assert!(step_inverse(&mut h,&mut p,&b,g).progress().fits(g));turns+=1;}if p.inverse_ready()&&turns<cut{let g=grant(p.inverse_take_demand().unwrap());inverse=Some(take_inverse(&mut h,&mut p,g).unwrap().0);}}close(&mut h,&mut p);assert_eq!(b.borrow().get().as_ref().map(|text|text.as_ptr()),pointer);drain(&mut h,change);drain(&mut h,inverse);close_source(&mut h,a);close_source(&mut h,b);close_source(&mut h,foreign);}}
 for(left,right,equal)in[(0.0f64,-0.0f64,true),(f64::NAN,f64::NAN,false),(1.0,2.0,false)]{let mut h=Harness::new();let mut l=source(&mut h,Some(left));let mut r=source(&mut h,Some(right));let mut c=RetainedFieldChange::<Option<f64>>::default();while !c.ready(){let g=grant(c.decision_demand(l.borrow(),r.borrow(),257,4096).unwrap());assert!(step_decide(&mut h,&mut c,&l,&r,g).progress().fits(g));}assert_eq!(c.equal,Some(equal));close(&mut h,&mut c);close_source(&mut h,l);close_source(&mut h,r);}}

#[test]
#[ignore = "array child producer is not yet available upstream (UnsupportedOwner)"]
fn optional_original_byte_pairs_compare_array_children(){
 for(left,right,equal)in[([vec![1u8,2],vec![3,4]],[vec![1u8,2],vec![3,4]],true),([vec![1u8,2],vec![3,4]],[vec![1u8,2],vec![3,5]],false),([vec![1u8,2],vec![3,4]],[vec![1u8],vec![3,4]],false)]{
 let mut h=Harness::new();let mut l=source(&mut h,Some(left));let mut r=source(&mut h,Some(right));let mut c=RetainedFieldChange::<Option<[Vec<u8>;2]>>::default();
 while !c.ready(){let g=grant(c.decision_demand(l.borrow(),r.borrow(),257,4096).unwrap());assert_eq!(step_decide(&mut h,&mut c,&l,&r,RetainedCloneGrant{maximum_items:0,..g}).progress(),Default::default());assert!(step_decide(&mut h,&mut c,&l,&r,g).progress().fits(g));}
 assert_eq!(c.equal,Some(equal));close(&mut h,&mut c);close_source(&mut h,l);close_source(&mut h,r);
 }
}

fn exercise_plain<T:RetainedEquality+RetainedClone+Clone>(authored:T,original:T,unchanged:bool,cut:Option<usize>,equivalent:impl Fn(&T,&T)->bool){let expected_change=authored.clone();let expected_inverse=original.clone();let mut h=Harness::new();let mut a=source(&mut h,authored);let mut b=source(&mut h,original);let mut foreign=source(&mut h,expected_change.clone());let(mut p,heap)=observe_heap(RetainedFieldChange::<T>::default);assert_eq!(heap,(0,0));let mut turns=0;while !p.ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.decision_demand(a.borrow(),b.borrow(),257,4096).unwrap());assert_eq!(step_decide(&mut h,&mut p,&a,&b,RetainedCloneGrant{maximum_copy_bytes:0,..g}).progress(),Default::default());assert!(step_decide(&mut h,&mut p,&a,&b,g).progress().fits(g));turns+=1;assert!(turns<100000);}if turns>0{assert!(p.equality.verify(foreign.borrow(),b.borrow()).is_err());}let mut change=None;let mut inverse=None;if p.ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.change_demand().unwrap());let(value,receipt)=take_change(&mut h,&mut p,g).unwrap();assert!(receipt.fits(g));assert_eq!(value.is_none(),unchanged);if let Some(value)=value.as_ref(){assert!(equivalent(value,&expected_change));}change=Some(value);turns+=1;while !p.inverse_ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.inverse_demand(b.borrow(),257,4096).unwrap());assert!(step_inverse(&mut h,&mut p,&b,g).progress().fits(g));turns+=1;assert!(turns<100000);}if p.inverse_ready()&&cut.is_none_or(|cut|turns<cut){let g=grant(p.inverse_take_demand().unwrap());let(value,receipt)=take_inverse(&mut h,&mut p,g).unwrap();assert!(receipt.fits(g));assert!(equivalent(&value,&expected_inverse));inverse=Some(value);}}close(&mut h,&mut p);assert_eq!(observe_heap(||drop(p)).1,(0,0));drain(&mut h,change);drain(&mut h,inverse);drain(&mut h,expected_change);drain(&mut h,expected_inverse);close_source(&mut h,a);close_source(&mut h,b);close_source(&mut h,foreign);}
#[test]
fn typed_field_changes_plain_text_bytes_and_ieee_preserve_original_children(){let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../🪡️field/🟰️change/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["plainCases"].as_array().unwrap(){for cut in fixture["cancelCuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain(std::iter::once(None)){let same=row["unchanged"].as_bool().unwrap();match row["type"].as_str().unwrap(){"text"=>exercise_plain(row["authored"].as_str().unwrap().to_owned(),row["original"].as_str().unwrap().to_owned(),same,cut,|a,b|a==b),"bytes"=>{let bytes=|v:&serde_json::Value|v.as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>();exercise_plain(bytes(&row["authored"]),bytes(&row["original"]),same,cut,|a,b|a==b)},"f64"=>{let number=|v:&serde_json::Value|if v=="nan"{f64::NAN}else{v.as_str().unwrap().parse::<f64>().unwrap()};exercise_plain(number(&row["authored"]),number(&row["original"]),same,cut,|a,b|a.to_bits()==b.to_bits());},_=>unreachable!()}}}}
